INSERT INTO execution_observations(action_id,user_id,state,receipt_id,error_code,observed_at)
SELECT #{actionId},#{userId},#{state},#{receiptId},#{errorCode},#{observedAt}
FROM actions WHERE id=#{actionId} AND user_id=#{userId}
  AND NOT EXISTS(SELECT 1 FROM execution_observations WHERE action_id=#{actionId} AND NOT(user_id <=> #{userId}))
ON DUPLICATE KEY UPDATE state=#{state},receipt_id=#{receiptId},error_code=#{errorCode},observed_at=#{observedAt}
